package com.bank.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class SortingDemo {

    private static final Logger log = Logger.getLogger(SortingDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        List<Txn> txns = new ArrayList<>(List.of(
            new Txn("T1", new BigDecimal("5000"),  LocalDate.of(2026, 10, 3)),
            new Txn("T2", new BigDecimal("1200"),  LocalDate.of(2026, 10, 1)),
            new Txn("T3", new BigDecimal("5000"),  LocalDate.of(2026, 10, 5)), // same amount as T1
            new Txn("T4", new BigDecimal("300"),   LocalDate.of(2026, 10, 2))
        ));

        StatementSorter sorter = new StatementSorter();

        log.info("Sorted by amount ASCENDING (stable — equal amounts keep date order):");
        sorter.byAmountAscending(txns).forEach(t -> log.info(() -> "  " + t.describe()));

        log.info("Sorted by amount DESCENDING:");
        sorter.byAmountDescending(txns).forEach(t -> log.info(() -> "  " + t.describe()));

        log.info("Sorted by DATE ascending:");
        sorter.byDate(txns).forEach(t -> log.info(() -> "  " + t.describe()));
    }
}

