class Txn {
    private final String id;
    private final BigDecimal amount;
    private final LocalDate date;

    Txn(String id, BigDecimal amount, LocalDate date) {
        this.id = id; this.amount = amount; this.date = date;
    }
    String getId() { return id; }
    BigDecimal getAmount() { return amount; }
    LocalDate getDate() { return date; }
    String describe() { return id + " Rs." + amount + " on " + date; }
}

// ─── Would be in service/StatementSorter.java in a real project ───
class StatementSorter {

    private static final Logger log = Logger.getLogger(StatementSorter.class.getName());

    List<Txn> byAmountAscending(List<Txn> txns) {
        List<Txn> copy = new ArrayList<>(txns);          // do not mutate caller's list
        copy.sort(java.util.Comparator.comparing(Txn::getAmount)); // stable TimSort
        return copy;
    }

    List<Txn> byAmountDescending(List<Txn> txns) {
        List<Txn> copy = new ArrayList<>(txns);
        copy.sort(java.util.Comparator.comparing(Txn::getAmount).reversed());
        return copy;
    }

    List<Txn> byDate(List<Txn> txns) {
        List<Txn> copy = new ArrayList<>(txns);
        copy.sort(java.util.Comparator.comparing(Txn::getDate));
        return copy;
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
